"""Offline ADB and length-prefixed plist exchange adapters."""
import base64
import plistlib
import struct

CNXN = 0x4e584e43
AUTH = 0x48545541
CLSE = 0x45534c43
ADB_BODY_LIMIT = 65535
SYNC_BODY_LIMIT = 65532
PRODUCT_KEYS = ('ProductVersion', 'ProductName')

_PARSE_ERRORS = (ValueError, TypeError, KeyError, IndexError, AttributeError,
                 OverflowError, RecursionError, struct.error, MemoryError,
                 plistlib.InvalidFileException)


def checksum(data):
    return sum(data) & 0xffffffff


def adb_packet(command, arg0, arg1, body):
    head = struct.pack('<6I', command, arg0, arg1, len(body), checksum(body),
                       command ^ 0xffffffff)
    return head + body


def send_connect():
    return adb_packet(CNXN, 0x01000000, 4096, b'host::zgrab2')


def send_close():
    return adb_packet(CLSE, 0, 0, b'')


def read_adb_response(data):
    """Parse exactly one ADB packet; raise ValueError on bad wire data."""
    if len(data) < 24:
        raise ValueError('short ADB packet')
    command, arg0, arg1, length, check, magic = struct.unpack('<6I', data[:24])
    if command ^ magic != 0xffffffff:
        raise ValueError('bad ADB header')
    if command == CNXN or command == AUTH:
        if length > ADB_BODY_LIMIT or len(data) != 24 + length:
            raise ValueError('bad ADB body length')
        body = data[24:]
        if checksum(body) != check:
            raise ValueError('bad ADB checksum')
        if command == CNXN:
            return ('CNXN', (arg0 >> 16) & 255, (arg0 >> 8) & 255, arg0 & 255,
                    body.decode('utf-8'))
        return ('AUTH', arg0, arg1, body)
    raise ValueError('unknown ADB command')


def get_value_request(key):
    value = plistlib.dumps({'Key': key, 'Label': 'usbmuxd', 'ProtocolVersion': '2',
                            'Request': 'GetValue'}, fmt=plistlib.FMT_XML,
                           sort_keys=False)
    return struct.pack('>I', len(value)) + value


def _frame(body):
    if not 1 <= len(body) <= SYNC_BODY_LIMIT:
        raise ValueError('bad sync frame length')
    return struct.pack('>I', len(body)) + body


def _get_value(body, key):
    try:
        value = plistlib.loads(body)
    except _PARSE_ERRORS:
        raise ValueError('bad plist') from None
    if not isinstance(value, dict) or set(value) != {'Key', 'Request', 'Value'}:
        raise ValueError('bad GetValue shape')
    if value['Request'] != 'GetValue':
        raise ValueError('bad GetValue request')
    text = value['Value']
    if not isinstance(text, str) or not text:
        raise ValueError('bad GetValue value')
    if value['Key'] != key:
        raise ValueError('bad GetValue key')
    return text


def read_sync_response(data):
    """Parse exactly two length-prefixed GetValue plists."""
    if len(data) < 8:
        raise ValueError('short sync payload')
    at = 0
    values = []
    for key in PRODUCT_KEYS:
        size = int.from_bytes(data[at:at + 4], 'big') if at + 4 <= len(data) else 0
        if not 1 <= size <= SYNC_BODY_LIMIT or at + 4 + size > len(data):
            raise ValueError('bad sync frame')
        values.append(_get_value(data[at + 4:at + 4 + size], key))
        at += 4 + size
    if at != len(data):
        raise ValueError('trailing sync data')
    return ('sync', values[0], values[1])


def send_messages(data):
    return read_sync_response(data)


def signature(kind, data):
    try:
        if kind == 'tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind == 'adb':
            return read_adb_response(data)
        return read_sync_response(data)
    except (ValueError, UnicodeError):
        return None


def probe_script(kind):
    encode = lambda b: base64.b64encode(b).decode('ascii')
    if kind == 'tcp':
        return [], []
    if kind == 'adb':
        return [encode(send_connect())], [encode(send_close())]
    return [encode(get_value_request(PRODUCT_KEYS[0])),
            encode(get_value_request(PRODUCT_KEYS[1]))], []
